CREATE SEQUENCE IF NOT EXISTS public.commercial_exception_seq;
GRANT USAGE, SELECT ON SEQUENCE public.commercial_exception_seq TO authenticated, service_role;
DO $$ BEGIN CREATE TYPE public.infra_di00_state AS ENUM ('DESIGN','CONFIGURATION_REQUIRED','CONFIGURED','PROVISIONING','PROVISIONED','CONNECTED', 'IDENTITY_VERIFIED','SCHEMA_READY','SECURITY_READY','BACKUP_READY','RESTORE_READY', 'CERTIFICATION_READY','CERTIFICATION_IN_PROGRESS','CERTIFIED','CLEARED', 'CONFIGURATION_FAILED','PROVISIONING_FAILED','CONNECTION_FAILED','IDENTITY_FAILED', 'SCHEMA_FAILED','SECURITY_FAILED','BACKUP_FAILED','RESTORE_FAILED','CERTIFICATION_FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.infra_environment_type AS ENUM ('DEVELOPMENT','TEST','STAGING','RESTORE','PRODUCTION'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.intern_pipeline_stage AS ENUM ('DRAFT','PUBLISHED','APPLICATION_OPEN','APPLICATION_RECEIVED','ELIGIBILITY_SCREENING', 'ACADEMIC_PROFILE_VALIDATION','CURRICULUM_MATCH','EVIDENCE_REVIEW','CAPABILITY_ASSESSMENT', 'SHORTLIST_REVIEW','INTERVIEW_INVITED','INTERVIEW_SCHEDULED','INTERVIEW_COMPLETED', 'SELECTION_REVIEW','SELECTED','OFFER_GENERATED','OFFER_SENT','OFFER_ACCEPTED', 'DOCUMENT_COLLECTION','ONBOARDING','INTERN_ACTIVATED','INTERNS_360', 'REJECTED','WITHDRAWN','DECLINED','EXPIRED','NO_SHOW','INELIGIBLE','POSITION_FILLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.st_exec_state AS ENUM ('REQUESTED','RUNNING','COMPLETED','FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.academy_enrollments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES public.academy_courses(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress','completed')), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE (user_id, course_id) );
CREATE TABLE IF NOT EXISTS public.academy_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor uuid, event_type text NOT NULL, entity text NOT NULL, entity_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.academy_lesson_progress ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, lesson_id uuid NOT NULL REFERENCES public.academy_lessons(id) ON DELETE CASCADE, course_id uuid NOT NULL REFERENCES public.academy_courses(id) ON DELETE CASCADE, completed_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, lesson_id) );
CREATE TABLE IF NOT EXISTS public.academy_manual_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version text NOT NULL UNIQUE, title text NOT NULL, summary text NOT NULL DEFAULT '', changelog text NOT NULL DEFAULT '', document_path text NOT NULL, page_count integer, status text NOT NULL DEFAULT 'published' CHECK (status IN ('draft','published','retired')), published_at timestamptz NOT NULL DEFAULT now(), created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.callback_endpoint_registry ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider TEXT NOT NULL, callback_url TEXT NOT NULL, environment TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true, last_certified_at TIMESTAMPTZ, last_certification_result TEXT, dns_status TEXT, tls_status TEXT, https_status TEXT, secret_valid BOOLEAN, deployment_reachable BOOLEAN, avg_latency_ms NUMERIC, health_score NUMERIC, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(provider, callback_url, environment) );
CREATE TABLE IF NOT EXISTS public.certification_scenarios_registry ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scenario_key text NOT NULL UNIQUE, scenario_name text NOT NULL, description text, workflow_key text NOT NULL, expected_outcome text NOT NULL, simulation_kind text NOT NULL, simulation_params jsonb NOT NULL DEFAULT '{}'::jsonb, timeout_ms integer NOT NULL DEFAULT 15000, retry_policy jsonb NOT NULL DEFAULT '{"max_attempts":1,"backoff_ms":0}'::jsonb, severity text NOT NULL DEFAULT 'high', enabled boolean NOT NULL DEFAULT true, last_run_at timestamptz, last_run_status text, last_run_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.certification_workflows ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workflow_key text NOT NULL UNIQUE, workflow_name text NOT NULL, description text, owner text, criticality text NOT NULL DEFAULT 'high', status text NOT NULL DEFAULT 'UNKNOWN', last_certified_at timestamptz, last_run_id uuid, score numeric(5,2), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_certification_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phase text NOT NULL DEFAULT '8.5', verdict text NOT NULL CHECK (verdict IN ('PASS','FAIL')), score numeric NOT NULL, criteria jsonb NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, run_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_ref text NOT NULL UNIQUE DEFAULT ('EXC-' || lpad(nextval('public.commercial_exception_seq')::text, 6, '0')), transaction_id uuid REFERENCES public.commercial_transactions(id) ON DELETE SET NULL, transaction_ref text, stage text NOT NULL, kind text NOT NULL, severity text NOT NULL DEFAULT 'medium', value_at_risk_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', loss_probability_pct numeric NOT NULL DEFAULT 50, customer_impact text NOT NULL DEFAULT 'none', operational_impact text NOT NULL DEFAULT 'low', strategic_weight numeric NOT NULL DEFAULT 1, priority_score numeric, sla_hours numeric NOT NULL DEFAULT 24, sla_due_at timestamptz, owner_team text NOT NULL DEFAULT 'finance', owner_user_id uuid, root_cause text, recommended_action text, escalation_level integer NOT NULL DEFAULT 0, notified_at timestamptz, notification_status text NOT NULL DEFAULT 'pending', status text NOT NULL DEFAULT 'open', resolution text, resolved_by uuid, resolved_at timestamptz, financial_impact_cents bigint, learning_outcome text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commercial_exceptions_severity_check CHECK (severity = ANY (ARRAY['low','medium','high','critical'])), CONSTRAINT commercial_exceptions_status_check CHECK (status = ANY (ARRAY['open','acknowledged','in_progress','escalated','resolved','accepted_risk','void'])), CONSTRAINT commercial_exceptions_notification_check CHECK (notification_status = ANY (ARRAY['pending','sent','failed','suppressed'])), CONSTRAINT commercial_exceptions_dedup UNIQUE (transaction_id, kind, status) );
CREATE TABLE IF NOT EXISTS public.infra_environments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment_key text NOT NULL UNIQUE, environment_name text NOT NULL, environment_type public.infra_environment_type NOT NULL, database_engine text NOT NULL DEFAULT 'postgresql', database_version text, provider text, provider_project_ref text, host_ref text, region text, deployment_reference text, database_reference text, credential_secret_name text, schema_version text, migration_version text, environment_fingerprint text, production_flag boolean NOT NULL DEFAULT false, synthetic_data_flag boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'REGISTERED', di00_state public.infra_di00_state NOT NULL DEFAULT 'CONFIGURATION_REQUIRED', di00_state_reason text, verification_status public.infra_check_result NOT NULL DEFAULT 'NOT_CONFIGURED', last_verified_at timestamptz, notes text, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT infra_env_no_production_certification CHECK ( NOT (production_flag AND environment_type IN ('STAGING','RESTORE'))), CONSTRAINT infra_env_credential_is_a_name CHECK ( credential_secret_name IS NULL OR credential_secret_name !~ '(?i)(postgres(ql)?://|password=)') );
CREATE TABLE IF NOT EXISTS public.intern_certification_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_by uuid, verdict text NOT NULL, gaps integer NOT NULL DEFAULT 0, total_checks integer NOT NULL DEFAULT 0, role_context text, result jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_curriculum_sources ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution text NOT NULL, institution_type text, programme text NOT NULL, qualification_level text NOT NULL, specialisation text, curriculum_version text NOT NULL DEFAULT 'v1', source text, source_url text, source_date date, retrieved_at timestamptz NOT NULL DEFAULT now(), verification_status text NOT NULL DEFAULT 'UNVERIFIED', review_due date, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.intern_learning_modules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), track_id uuid NOT NULL REFERENCES public.intern_tracks(id) ON DELETE CASCADE, code text NOT NULL, title text NOT NULL, competency text NOT NULL, sequence int NOT NULL DEFAULT 0, hours numeric(6,2) NOT NULL DEFAULT 2, requires_practical boolean NOT NULL DEFAULT true, resource_url text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (track_id, code) );
CREATE TABLE IF NOT EXISTS public.intern_recruitment_certification_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_by uuid, verdict text NOT NULL, total_checks integer NOT NULL, passed_checks integer NOT NULL, gaps jsonb NOT NULL DEFAULT '[]'::jsonb, result jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_recruitment_weight_sets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'ACTIVE', weights jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.legal_certifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, holder_type text NOT NULL DEFAULT 'platform', holder_id uuid, holder_name text, certification_type text NOT NULL, certificate_number text, issuer text, issue_date date, effective_from date, effective_until date, document_path text, verification_status public.legal_review_outcome NOT NULL DEFAULT 'pending', owner_user_id uuid, notes text, status public.legal_status NOT NULL DEFAULT 'evidence_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_training_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), model_name TEXT NOT NULL, run_name TEXT, status TEXT NOT NULL DEFAULT 'queued', dataset_ref TEXT, hyperparameters JSONB NOT NULL DEFAULT '{}'::jsonb, metrics JSONB NOT NULL DEFAULT '{}'::jsonb, artifact_uri TEXT, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, duration_seconds INTEGER, triggered_by UUID, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_applications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE DEFAULT ('YP-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), organisation_name text NOT NULL, partner_type public.partner_type NOT NULL DEFAULT 'OTHER', category text, commercial_model public.partner_commercial_model NOT NULL DEFAULT 'BOOK', contact_name text NOT NULL, contact_email text NOT NULL, contact_phone text NOT NULL, country text NOT NULL DEFAULT 'KE', city text, website text, monthly_volume_estimate integer, requirements text, status text NOT NULL DEFAULT 'submitted', review_notes text, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at timestamptz, partner_id uuid REFERENCES public.partners(id) ON DELETE SET NULL, submitted_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_onboarding_requirements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, label text NOT NULL, description text, partner_types public.partner_type[] NOT NULL DEFAULT '{}', is_mandatory boolean NOT NULL DEFAULT true, validity_months integer, sort_order integer NOT NULL DEFAULT 100, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.platform_certification_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), snapshot_id text NOT NULL, generated_at timestamptz NOT NULL DEFAULT now(), refreshed_at timestamptz NOT NULL DEFAULT now(), maturity_score integer NOT NULL, release_approved boolean NOT NULL DEFAULT false, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.projection_replay_certifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_attempt_id uuid NOT NULL, correlation_id text, before_hash text NOT NULL, after_hash text NOT NULL, equal boolean NOT NULL, passed boolean NOT NULL, expected_delta jsonb NOT NULL DEFAULT '{}'::jsonb, before_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, after_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, replay_result jsonb NOT NULL DEFAULT '{}'::jsonb, duration_ms int, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_import_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_no text NOT NULL UNIQUE, kind text NOT NULL DEFAULT 'document_seed' CHECK (kind IN ('document_seed','candidate_import','evaluation_seed','cv_enrichment')), label text NOT NULL, initiated_by uuid, initiated_by_label text NOT NULL DEFAULT 'Recruitment Operations', source_description text, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'completed' CHECK (status IN ('running','completed','completed_with_conflicts','failed')), stats jsonb NOT NULL DEFAULT '{}'::jsonb, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_job_descriptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, version integer NOT NULL DEFAULT 1, summary text, body text NOT NULL DEFAULT '', responsibilities text[] NOT NULL DEFAULT '{}', requirements text[] NOT NULL DEFAULT '{}', benefits text[] NOT NULL DEFAULT '{}', origin text NOT NULL DEFAULT 'human' CHECK (origin IN ('human','ai_draft','blueprint','template')), ai_model text, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','in_review','approved','published','archived')), approved_by uuid, approved_at timestamptz, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vacancy_id, version) );
CREATE TABLE IF NOT EXISTS public.rec_onboarding_tasks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES public.rec_onboarding_cases(id) ON DELETE CASCADE, title text NOT NULL, category text NOT NULL DEFAULT 'general' CHECK (category IN ('general','documents','compliance','equipment','access','orientation','training')), owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, due_date date, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','completed','blocked','waived')), completed_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.scheduled_job_invocations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_name text NOT NULL, function_slug text NOT NULL, request_id bigint, invoked_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.st_certification_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_key text NOT NULL UNIQUE, trigger_source text NOT NULL DEFAULT 'MANUAL', requested_by uuid, actor text NOT NULL DEFAULT 'st-orchestrator', state public.st_exec_state NOT NULL DEFAULT 'REQUESTED', correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, summary jsonb NOT NULL DEFAULT '{}'::jsonb, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, duration_ms integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_categories ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, description text, icon text, sort_order int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_cpd_points ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, source_type text NOT NULL, source_id uuid, points int NOT NULL, year int NOT NULL DEFAULT extract(year FROM now())::int, awarded_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_certification_gaps ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.commercial_certification_runs(id) ON DELETE CASCADE, transaction_id uuid, transaction_ref text, case_kind text NOT NULL, service_line text, failed_gate text NOT NULL, missing_fields text[] NOT NULL DEFAULT ARRAY[]::text[], blockers text[] NOT NULL DEFAULT ARRAY[]::text[], missing_stages text[] NOT NULL DEFAULT ARRAY[]::text[], exposure_cents bigint NOT NULL DEFAULT 0, detail text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_decision_learning ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid REFERENCES public.commercial_actions(id) ON DELETE SET NULL, transaction_id uuid REFERENCES public.commercial_transactions(id) ON DELETE SET NULL, exception_id uuid REFERENCES public.commercial_exceptions(id) ON DELETE SET NULL, decision text NOT NULL, hypothesis text, action_taken text, result text, variance_pct numeric, cause text, learning text NOT NULL, rule_or_model text, rule_update_applied boolean NOT NULL DEFAULT false, confidence_pct numeric CHECK (confidence_pct IS NULL OR (confidence_pct BETWEEN 0 AND 100)), evidence jsonb NOT NULL DEFAULT '{}'::jsonb, recorded_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_backups ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), backup_reference text NOT NULL UNIQUE DEFAULT ('BKP-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), source_environment_id uuid NOT NULL REFERENCES public.infra_environments(id) ON DELETE CASCADE, idempotency_key text NOT NULL, correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, request_id text NOT NULL DEFAULT gen_random_uuid()::text, requested_by uuid, state public.infra_job_state NOT NULL DEFAULT 'REQUESTED', backup_type text NOT NULL DEFAULT 'LOGICAL_SYNTHETIC', database_identity text, schema_version text, object_count integer, row_count integer, size_bytes bigint, checksum_sha256 text, storage_path text, provider_reference text, integrity_result public.infra_check_result NOT NULL DEFAULT 'UNKNOWN', error_code text, error_message text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, duration_ms integer, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (source_environment_id, idempotency_key) );
CREATE TABLE IF NOT EXISTS public.infrastructure_certification_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), endpoint_id UUID REFERENCES public.callback_endpoint_registry(id) ON DELETE CASCADE, callback_url TEXT NOT NULL, ran_at TIMESTAMPTZ NOT NULL DEFAULT now(), dns_ok BOOLEAN, tls_ok BOOLEAN, https_ok BOOLEAN, cert_valid BOOLEAN, secret_ok BOOLEAN, deployment_ok BOOLEAN, http_status INTEGER, latency_ms INTEGER, overall_ok BOOLEAN, failure_reason TEXT, raw_evidence JSONB NOT NULL DEFAULT '{}' );
CREATE TABLE IF NOT EXISTS public.intern_course_competencies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES public.intern_curriculum_sources(id) ON DELETE SET NULL, course text NOT NULL, competency text NOT NULL, competency_category text, yalla_capability text NOT NULL, track_code text, proficiency_signal text NOT NULL DEFAULT 'EXPOSURE', match_kind text NOT NULL DEFAULT 'PRIMARY', curriculum_version text NOT NULL DEFAULT 'v1', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (course, competency, curriculum_version) );
CREATE TABLE IF NOT EXISTS public.intern_learning_progress ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, module_id uuid NOT NULL REFERENCES public.intern_learning_modules(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'assigned' CHECK (status IN ('assigned','in_progress','submitted','validated','failed')), assessment_score numeric(5,2) CHECK (assessment_score IS NULL OR assessment_score BETWEEN 0 AND 100), attempts int NOT NULL DEFAULT 0, application_evidence text, started_at timestamptz, completed_at timestamptz, validated_by uuid, validated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (intern_id, module_id) );
CREATE TABLE IF NOT EXISTS public.intern_recruitment_pipeline ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL UNIQUE REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, programme_id uuid REFERENCES public.intern_programmes(id) ON DELETE SET NULL, cohort_id uuid REFERENCES public.intern_cohorts(id) ON DELETE SET NULL, primary_track_id uuid REFERENCES public.intern_tracks(id) ON DELETE SET NULL, secondary_track_id uuid REFERENCES public.intern_tracks(id) ON DELETE SET NULL, development_track_id uuid REFERENCES public.intern_tracks(id) ON DELETE SET NULL, intern_id uuid REFERENCES public.intern_profiles(id) ON DELETE SET NULL, stage public.intern_pipeline_stage NOT NULL DEFAULT 'APPLICATION_RECEIVED', stage_entered_at timestamptz NOT NULL DEFAULT now(), last_action_at timestamptz NOT NULL DEFAULT now(), sla_target_hours integer NOT NULL DEFAULT 72, eligibility_status text NOT NULL DEFAULT 'REVIEW_REQUIRED', eligibility_reasons jsonb NOT NULL DEFAULT '[]'::jsonb, curriculum_score numeric, evidence_score numeric, assessment_score numeric, interview_score numeric, match_score numeric, score_breakdown jsonb NOT NULL DEFAULT '{}'::jsonb, scoring_weight_set_id uuid REFERENCES public.intern_recruitment_weight_sets(id) ON DELETE SET NULL, screening_recommendation text, selection_decision text, selection_reason text, decided_by uuid, decided_at timestamptz, risk_flags jsonb NOT NULL DEFAULT '[]'::jsonb, owner_staff_id uuid, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, CONSTRAINT pipeline_eligibility_ck CHECK (eligibility_status IN ('ELIGIBLE','CONDITIONALLY_ELIGIBLE','INELIGIBLE','REVIEW_REQUIRED')), CONSTRAINT pipeline_screening_ck CHECK (screening_recommendation IS NULL OR screening_recommendation IN ('ADVANCE','REVIEW','HOLD','REJECT')) );
CREATE TABLE IF NOT EXISTS public.partner_recruitment_links ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, partner_application_id uuid NOT NULL UNIQUE REFERENCES public.partner_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, application_id uuid REFERENCES public.rec_applications(id) ON DELETE SET NULL, state text NOT NULL DEFAULT 'CANDIDATE_LINKED' CHECK (state IN ('CANDIDATE_LINKED','REQUISITION_LINKED')), notes text, linked_by uuid, linked_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_import_job_steps ( id uuid primary key default gen_random_uuid(), run_id uuid not null references public.rec_import_runs(id) on delete cascade, step_no int not null, step_key text not null, label text not null, handler text not null, status text not null default 'pending' check (status in ('pending','running','completed','failed','skipped')), attempts int not null default 0, max_attempts int not null default 3, next_attempt_at timestamptz, last_error text, payload jsonb not null default '{}'::jsonb, result jsonb, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (run_id, step_key) );
CREATE TABLE IF NOT EXISTS public.training_courses ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, slug text NOT NULL UNIQUE, title text NOT NULL, level int NOT NULL DEFAULT 0, category_id uuid REFERENCES public.training_categories(id) ON DELETE SET NULL, description text, duration_minutes int NOT NULL DEFAULT 0, pass_mark int NOT NULL DEFAULT 80, required_for_activation boolean NOT NULL DEFAULT false, certification_kind text, cpd_points int NOT NULL DEFAULT 0, is_published boolean NOT NULL DEFAULT true, sort_order int NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_restores ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restore_reference text NOT NULL UNIQUE DEFAULT ('RST-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), backup_id uuid NOT NULL REFERENCES public.infra_backups(id) ON DELETE RESTRICT, target_environment_id uuid NOT NULL REFERENCES public.infra_environments(id) ON DELETE CASCADE, idempotency_key text NOT NULL, correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, request_id text NOT NULL DEFAULT gen_random_uuid()::text, requested_by uuid, state public.infra_job_state NOT NULL DEFAULT 'REQUESTED', target_identity text, restored_object_count integer, restored_row_count integer, verification_result public.infra_check_result NOT NULL DEFAULT 'UNKNOWN', verification_detail jsonb NOT NULL DEFAULT '{}'::jsonb, error_code text, error_message text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, duration_ms integer, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (target_environment_id, idempotency_key) );
CREATE TABLE IF NOT EXISTS public.intern_recruitment_transitions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pipeline_id uuid NOT NULL REFERENCES public.intern_recruitment_pipeline(id) ON DELETE CASCADE, from_stage public.intern_pipeline_stage, to_stage public.intern_pipeline_stage NOT NULL, actor_id uuid, actor_email text, reason text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, idempotency_key text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (pipeline_id, idempotency_key) );
CREATE TABLE IF NOT EXISTS public.training_certificates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES public.training_courses(id), certificate_number text NOT NULL UNIQUE, kind text NOT NULL, title text NOT NULL, score numeric(5,2), qr_payload text NOT NULL, signature_hash text NOT NULL, issued_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, revoked_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_enrollments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES public.training_courses(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'in_progress', enrolled_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, progress_pct int NOT NULL DEFAULT 0, UNIQUE(driver_id, course_id) );
CREATE TABLE IF NOT EXISTS public.training_modules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.training_courses(id) ON DELETE CASCADE, code text, title text NOT NULL, description text, sort_order int NOT NULL DEFAULT 0, duration_minutes int NOT NULL DEFAULT 0, pass_mark int, is_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_certifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), certification_reference text NOT NULL UNIQUE DEFAULT ('DI00-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), control_id text NOT NULL DEFAULT 'DI-00', outcome public.infra_check_result NOT NULL, di00_state public.infra_di00_state NOT NULL, staging_environment_id uuid REFERENCES public.infra_environments(id), restore_environment_id uuid REFERENCES public.infra_environments(id), backup_id uuid REFERENCES public.infra_backups(id), restore_id uuid REFERENCES public.infra_restores(id), criteria jsonb NOT NULL, blockers jsonb NOT NULL DEFAULT '[]'::jsonb, correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, request_id text NOT NULL DEFAULT gen_random_uuid()::text, executed_by uuid, executed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_assessments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.training_courses(id) ON DELETE CASCADE, module_id uuid REFERENCES public.training_modules(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'final', title text NOT NULL, description text, pass_mark int NOT NULL DEFAULT 80, time_limit_min int, max_attempts int NOT NULL DEFAULT 3, randomize boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_lessons ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.training_modules(id) ON DELETE CASCADE, title text NOT NULL, lesson_type text NOT NULL DEFAULT 'reading', content_md text, duration_minutes int NOT NULL DEFAULT 0, sort_order int NOT NULL DEFAULT 0, is_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, assessment_id uuid NOT NULL REFERENCES public.training_assessments(id) ON DELETE CASCADE, course_id uuid NOT NULL, answers jsonb NOT NULL DEFAULT '{}'::jsonb, score numeric(5,2), passed boolean, started_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES public.training_lessons(id) ON DELETE CASCADE, title text NOT NULL, url text NOT NULL, kind text NOT NULL DEFAULT 'pdf', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_progress ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, course_id uuid NOT NULL, lesson_id uuid NOT NULL REFERENCES public.training_lessons(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'in_progress', progress_pct int NOT NULL DEFAULT 0, last_position_seconds int NOT NULL DEFAULT 0, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(driver_id, lesson_id) );
CREATE TABLE IF NOT EXISTS public.training_questions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES public.training_assessments(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'mcq', prompt text NOT NULL, image_url text, video_url text, explanation text, points int NOT NULL DEFAULT 1, sort_order int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_videos ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES public.training_lessons(id) ON DELETE CASCADE, provider text NOT NULL DEFAULT 'youtube', url text NOT NULL, title text, duration_seconds int NOT NULL DEFAULT 0, min_watch_percent int NOT NULL DEFAULT 90, checkpoints jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.training_answers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES public.training_questions(id) ON DELETE CASCADE, label text NOT NULL, is_correct boolean NOT NULL DEFAULT false, sort_order int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.commercial_exceptions ADD COLUMN IF NOT EXISTS assigned_to uuid, ADD COLUMN IF NOT EXISTS assigned_by uuid, ADD COLUMN IF NOT EXISTS assigned_at timestamptz, ADD COLUMN IF NOT EXISTS acknowledged_by uuid, ADD COLUMN IF NOT EXISTS acknowledged_at timestamptz, ADD COLUMN IF NOT EXISTS triaged_by uuid, ADD COLUMN IF NOT EXISTS triaged_at timestamptz, ADD COLUMN IF NOT EXISTS triage_notes text, ADD COLUMN IF NOT EXISTS sla_breached_at timestamptz;
ALTER TABLE public.partner_applications ADD COLUMN IF NOT EXISTS intent_bring text, ADD COLUMN IF NOT EXISTS network_category text, ADD COLUMN IF NOT EXISTS maturity_level text, ADD COLUMN IF NOT EXISTS lifecycle_stage text, ADD COLUMN IF NOT EXISTS ab_variant text, ADD COLUMN IF NOT EXISTS session_id text;
ALTER TABLE public.partner_applications ADD COLUMN IF NOT EXISTS carrier_application_id uuid, ADD COLUMN IF NOT EXISTS carrier_id uuid REFERENCES public.carrier_profiles(id), ADD COLUMN IF NOT EXISTS converted_at timestamptz, ADD COLUMN IF NOT EXISTS converted_by uuid, ADD COLUMN IF NOT EXISTS review_status text;
ALTER TABLE public.partner_applications ADD COLUMN IF NOT EXISTS client_fingerprint text;
ALTER TABLE public.rec_import_runs add column if not exists locked_until timestamptz, add column if not exists paused_reason text;
ALTER TABLE public.training_videos ADD COLUMN IF NOT EXISTS is_mandatory boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS sort_order integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS checkpoint_count integer NOT NULL DEFAULT 5, ADD COLUMN IF NOT EXISTS external_code text;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['academy_enrollments','academy_events','academy_lesson_progress','academy_manual_versions','callback_endpoint_registry','certification_scenarios_registry','certification_workflows','commercial_certification_runs','commercial_exceptions','infra_environments','intern_certification_runs','intern_curriculum_sources','intern_learning_modules','intern_recruitment_certification_runs','intern_recruitment_weight_sets','legal_certifications','ml_training_runs','partner_applications','partner_onboarding_requirements','platform_certification_snapshots','projection_replay_certifications','rec_import_runs','rec_job_descriptions','rec_onboarding_tasks','scheduled_job_invocations','st_certification_runs','training_categories','training_cpd_points','commercial_certification_gaps','commercial_decision_learning','infra_backups','infrastructure_certification_runs','intern_course_competencies','intern_learning_progress','intern_recruitment_pipeline','partner_recruitment_links','rec_import_job_steps','training_courses','infra_restores','intern_recruitment_transitions','training_certificates','training_enrollments','training_modules','infra_certifications','training_assessments','training_lessons','training_attempts','training_documents','training_progress','training_questions','training_videos','training_answers'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[]))', t); END LOOP; END $$;
